// Generated by Cypress Author on 2026-10-22
//
// CON 01 · CON 02 (UI) — Plano_de_Testes_QA_MatchWallet.md §11 (docs-test/areas/con.md).
//
// ATENÇÃO — `services/conta.ts` é MOCK: `atualizar()` só espera 600 ms e devolve o payload, sem
// chamar `PATCH /auth/me`. Por isso os testes marcados "(falha até integrar)" exigem que o PATCH
// saia do navegador e devem FALHAR hoje; os demais valem para o mock e para a integração real.
// CON 03–06 não têm teste: não há UI nem endpoint (ver cypress/README.md, "Sem teste").

const ME = {
  id: '11111111-1111-4111-8111-111111111111',
  nome: 'Maria Teste',
  email: 'maria@teste.com',
  perfil: 'cliente',
  perfilInvestidor: 'MODERADO',
  carteiraVinculada: null,
}

const NOVO = { nome: 'José Ândré Çavalcante', email: 'jose.andre@teste.com' }

/** `/auth/me` e `PATCH /auth/me` com estado: o reload devolve o que o PATCH gravou. */
function stubConta(respostaPatch?: object) {
  const servidor = { ...ME }

  cy.bloquearApi()
  cy.intercept('GET', '**/api/v1/auth/me', (req) => req.reply(servidor)).as('me')
  cy.intercept('PATCH', '**/api/v1/auth/me', (req) => {
    if (respostaPatch) {
      req.reply(respostaPatch)
      return
    }
    Object.assign(servidor, req.body)
    req.reply(servidor)
  }).as('patch')
}

function abrirEdicao() {
  cy.get('[aria-label="Editar dados da conta"]').click()
  cy.get('[role="dialog"]').should('be.visible')
}

function preencher(nome: string, email: string) {
  cy.get('input[name="nome"]').clear().type(nome)
  cy.get('input[name="email"]').clear().type(email)
}

function dadosDaConta() {
  return cy.contains('h2', 'Dados').parents('section').first()
}

describe('Plano QA · Conta · edição de dados', () => {
  it('CON 01 · altera nome e e-mail e recarrega → PATCH com os dados, mesma conta e valores persistidos (falha até integrar)', () => {
    stubConta()
    cy.visit('/conta')
    dadosDaConta().should('contain.text', ME.nome).and('contain.text', ME.email)

    abrirEdicao()
    // O formulário abre com os dados atuais.
    cy.get('input[name="nome"]').should('have.value', ME.nome)
    cy.get('input[name="email"]').should('have.value', ME.email)
    preencher(NOVO.nome, NOVO.email)
    cy.contains('button', 'Salvar alterações').click()

    cy.contains('Dados da conta atualizados').should('be.visible')
    cy.get('[role="dialog"]').should('not.exist')
    dadosDaConta().should('contain.text', NOVO.nome).and('contain.text', NOVO.email)

    // Falha hoje: o mock não envia nada ao servidor.
    cy.wait('@patch', { timeout: 2000 }).its('request.body').should('deep.equal', NOVO)

    // Recarrega: o que aparece vem do servidor, não do estado local da sessão.
    cy.reload()
    cy.wait('@me')
    dadosDaConta().should('contain.text', NOVO.nome).and('contain.text', NOVO.email)
    dadosDaConta().should('not.contain.text', ME.nome)
    // Mesma conta (nenhum cadastro novo): `/auth/me` segue devolvendo o mesmo id.
    cy.get('@me.all').its('length').should('be.gte', 2)
  })

  it('CON 02 · nome vazio/espaços e e-mail inválido → mensagens de validação e nenhum envio', () => {
    stubConta()
    cy.visit('/conta')
    abrirEdicao()

    // Nome vazio e só espaços caem na mesma regra (o schema apara antes de validar).
    for (const nome of ['', '     ', 'ab']) {
      cy.get('input[name="nome"]').clear()
      if (nome) cy.get('input[name="nome"]').type(nome)
      cy.contains('button', 'Salvar alterações').click()
      cy.contains('O nome precisa ter ao menos 3 caracteres').should('be.visible')
    }

    // E-mail aceito pelo navegador mas recusado pelo schema.
    cy.get('input[name="nome"]').clear().type(ME.nome)
    cy.get('input[name="email"]').clear().type('maria@teste')
    cy.contains('button', 'Salvar alterações').click()
    cy.contains('Informe um e-mail válido').should('be.visible')

    // E-mail vazio.
    cy.get('input[name="email"]').clear()
    cy.contains('button', 'Salvar alterações').click()
    cy.contains('Informe um e-mail válido').should('be.visible')

    // E-mail sem "@": barrado pela validação nativa do input type=email, antes do submit.
    cy.get('input[name="email"]').type('sem-arroba')
    cy.contains('button', 'Salvar alterações').click()
    cy.get('input[name="email"]').then(($input) => {
      expect(($input[0] as HTMLInputElement).validity.valid).to.eq(false)
    })

    cy.get('[role="dialog"]').should('be.visible')
    cy.get('@patch.all').should('have.length', 0)
    dadosDaConta().should('contain.text', ME.nome).and('contain.text', ME.email)
  })

  it('CON 02 · altera os campos e cancela/fecha → dados anteriores mantidos e sem envio', () => {
    stubConta()
    cy.visit('/conta')

    // Botão Cancelar.
    abrirEdicao()
    preencher(NOVO.nome, NOVO.email)
    cy.contains('[role="dialog"] button', 'Cancelar').click()
    cy.get('[role="dialog"]').should('not.exist')
    dadosDaConta().should('contain.text', ME.nome).and('contain.text', ME.email)

    // Reabrir mostra os dados atuais, não o rascunho descartado.
    abrirEdicao()
    cy.get('input[name="nome"]').should('have.value', ME.nome)
    cy.get('input[name="email"]').should('have.value', ME.email)

    // Esc também descarta.
    preencher(NOVO.nome, NOVO.email)
    cy.get('body').type('{esc}')
    cy.get('[role="dialog"]').should('not.exist')
    dadosDaConta().should('contain.text', ME.nome).and('not.contain.text', NOVO.nome)

    cy.get('@patch.all').should('have.length', 0)
  })

  it('CON 02 · servidor recusa e-mail duplicado (409) → erro visível, diálogo aberto e dados anteriores (falha até integrar)', () => {
    stubConta({
      statusCode: 409,
      body: { error: { code: 'EMAIL_IN_USE', message: 'E-mail já cadastrado.' } },
    })
    cy.visit('/conta')
    abrirEdicao()
    preencher(ME.nome, 'outra.pessoa@teste.com')
    cy.contains('button', 'Salvar alterações').click()

    // Falha hoje: o mock nunca chama o servidor, então a recusa não acontece.
    cy.wait('@patch', { timeout: 2000 })
    cy.contains('Dados da conta atualizados').should('not.exist')
    cy.contains('Não foi possível salvar as alterações agora.').should('be.visible')
    cy.get('[role="dialog"]').should('be.visible')
    dadosDaConta()
      .should('contain.text', ME.email)
      .and('not.contain.text', 'outra.pessoa@teste.com')
  })
})

export {}
